import time
import datetime
from copy import deepcopy

from .logger import LOGGER


def remove_alarms_not_in_time_frame(alarms, time_start, time_end):
    """
    Remove alarms not in time frame (time_start:time_end)
    :param alarms: (list) list of dicts with alarms data
    :param time_start: (string) timestamp for alarms check
    :param time_end: (string) end timestamp for alarms check
    :return: list of alarms in time frame (time_start:time_end)
    """
    for alarm_data in alarms:
        alarm_time = alarm_data['time']
        alarm_time = time.strptime(alarm_time.split('.')[0], '%H:%M:%S')
        alarm_time_in_seconds = datetime.timedelta(hours=alarm_time.tm_hour, minutes=alarm_time.tm_min,
                                                   seconds=alarm_time.tm_sec).total_seconds()
        if alarm_time_in_seconds > time_end or alarm_time_in_seconds < time_start:
            alarms.remove(alarm_data)
    return alarms


def remove_matched_alarms(list_of_alarms=[], list_of_alarms_patterns=[]):
    """Remove from the alarm list alarms matching patterns, and returns a new list"""
    matched_exp, not_matched_exp, not_matched_alarms = match_alarms(list_of_alarms_patterns, list_of_alarms)
    return matched_exp, not_matched_exp, not_matched_alarms


def match_alarms(expected_alarms, alarms):
    matched_exp = []
    not_matched_exp = []
    not_matched_alarms = deepcopy(alarms)
    for exc_alarm in expected_alarms:
        for alarm in alarms:
            if _compare_alarms(exc_alarm, alarm):
                matched_exp.append(exc_alarm)
                if alarm in not_matched_alarms:
                    not_matched_alarms.remove(alarm)
                continue
        if exc_alarm not in matched_exp:
            not_matched_exp.append(exc_alarm)
    unexpected_amount, missing_amount = _verify_alarms_amount(expected_alarms, matched_exp)
    not_matched_exp.extend(missing_amount)
    not_matched_alarms.extend(unexpected_amount)
    return matched_exp, not_matched_exp, not_matched_alarms


def _compare_alarms(expected_under_check, existing_alarm):
    for key, value in expected_under_check.items():
        if key != 'amount':
            if existing_alarm[key] == value:
                continue
            elif isinstance(existing_alarm[key], (tuple, list)) and isinstance(value, (tuple, list)):
                if set(value).issubset(existing_alarm[key]):
                    continue
                else:
                    return False
            else:
                return False
    return True


def _verify_alarms_amount(expected_alarms, founded_alarms):  # noqa: C901
    unexpected, missing = [], []
    for alarm in expected_alarms:
        LOGGER.debug('Alarm under check: {}'.format(alarm))
        if 'amount' in alarm:
            amount = int(alarm['amount'])
            no_of_alarm = founded_alarms.count(alarm)
            if no_of_alarm == amount:
                LOGGER.debug('Alarm amount match')
            elif no_of_alarm > amount:
                LOGGER.debug('Found to much occurrence. Expected: {} / founded {}'.format(amount, no_of_alarm))
                for i in range(no_of_alarm - amount):
                    unexpected.append(alarm)
            elif no_of_alarm < amount:
                LOGGER.debug('Found not enough occurrence. Expected: {} / founded {}'.format(amount, no_of_alarm))
                for i in range(amount - no_of_alarm):
                    missing.append(alarm)
    return unexpected, missing
